{
  "iteration": 1,
  "pcvs": [
    {
      "name": "sampling_copy_count",
      "expression": "int(not self.all_greedy) + int(not self.no_top_p) + int(not self.no_top_k) + 3 * int(not self.no_penalties)",
      "rationale": "Counts conditional sampling tensor copies, each with substantial fixed library overhead."
    },
    {
      "name": "needs_prompt_tokens",
      "expression": "int(not self.no_penalties or self.logits_processing_needs_token_ids[:self.num_reqs].any())",
      "rationale": "Captures the fixed allocation and conversion cost of constructing prompt token metadata."
    },
    {
      "name": "prompt_rows",
      "expression": "self.num_reqs if (not self.no_penalties or self.logits_processing_needs_token_ids[:self.num_reqs].any()) else 0",
      "rationale": "Tracks iterations of the per-request prompt padding loop."
    },
    {
      "name": "prompt_elements",
      "expression": "self.num_reqs * int(self.num_prompt_tokens[:self.num_reqs].max()) if self.num_reqs and (not self.no_penalties or self.logits_processing_needs_token_ids[:self.num_reqs].any()) else 0",
      "rationale": "Tracks the rectangular prompt tensor size copied and converted."
    }
  ],
  "hypothesis": "Instruction count is primarily explained by conditional tensor-copy overhead and prompt tensor construction, with additional costs proportional to prompt rows and elements."
}
